import { readDetailRoute } from "../../lib/entity-details";
import { readStrictness, searchConfiguration } from "../../lib/search";
import { loadDetails } from "../../lib/server/entity-details";
import { searchEntities } from "../../lib/server/search";
import type { PageModel } from "../../lib/page";
import type { PageServerLoad } from "./$types";
export const load = (async ({ url, fetch, request, depends }) => {
  depends("exposed:page");
  const route = readDetailRoute(url.pathname);
  const origin = (
    process.env.EXPOSED_API_ORIGIN || "http://127.0.0.1:6999"
  ).replace(/\/$/, "");
  let model: PageModel;
  if (route.kind !== "search") {
    model = {
      kind: "detail",
      route,
      result:
        route.kind === "invalid"
          ? { kind: "not-found" }
          : await loadDetails(route, request.signal, fetch, origin),
    };
  } else {
    const query = url.searchParams.get("q") ?? "";
    const strictness = readStrictness(url.searchParams.get("strictness"));
    const term = query.trim();
    model = { kind: "search", query, strictness, result: { status: "idle" } };
    if ([...term].length >= searchConfiguration.minimumCharacters) {
      try {
        model.result = {
          status: "success",
          term,
          entities: await searchEntities(
            term,
            request.signal,
            strictness,
            fetch,
            origin,
          ),
        };
      } catch (error) {
        model.result = {
          status: "error",
          term,
          message:
            error instanceof Error
              ? error.message
              : "Search couldn’t load. Try again.",
        };
      }
    }
  }
  return { model };
}) satisfies PageServerLoad;

import {
  searchConfiguration,
  type Entity,
  type SearchMatchSource,
} from "../search";
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function readEntities(body: unknown): Entity[] {
  if (!isRecord(body) || !Array.isArray(body.entities)) {
    throw new Error("Search returned an unexpected response. Try again.");
  }

  return body.entities.map((value: unknown) => {
    if (
      !isRecord(value) ||
      typeof value.name !== "string" ||
      typeof value.id !== "string" ||
      (value.kind !== "MP" && value.kind !== "Funder") ||
      (value.funder_kind !== null && typeof value.funder_kind !== "string")
    ) {
      throw new Error("Search returned an unexpected response. Try again.");
    }
    const source = value.match_source;
    if (!isRecord(source))
      throw new Error("Search returned an unexpected match source. Try again.");
    let matchSource: SearchMatchSource;
    switch (source.kind) {
      case "name":
        matchSource = { kind: "name" };
        break;
      case "alias":
        if (typeof source.name !== "string" || !source.name.trim())
          throw new Error(
            "Search returned an unexpected match source. Try again.",
          );
        matchSource = { kind: "alias", name: source.name };
        break;
      default:
        throw new Error(
          "Search returned an unexpected match source. Try again.",
        );
    }
    if (value.kind === "MP") {
      if (
        !/^[1-9]\d*$/u.test(value.id) ||
        Number(value.id) > 2147483647 ||
        value.funder_kind !== null ||
        matchSource.kind !== "name"
      )
        throw new Error(
          "Search returned an unexpected MP identity. Try again.",
        );
      return {
        id: value.id,
        name: value.name,
        kind: "MP",
        funderKind: null,
        matchSource,
      };
    }
    if (
      !/^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/iu.test(
        value.id,
      )
    )
      throw new Error(
        "Search returned an unexpected funder identity. Try again.",
      );
    return {
      id: value.id,
      name: value.name,
      kind: "Funder",
      funderKind: value.funder_kind,
      matchSource,
    };
  });
}

export async function searchEntities(
  term: string,
  signal: AbortSignal,
  strictness: number,
  fetch: typeof globalThis.fetch,
  origin: string,
): Promise<Entity[]> {
  const controller = new AbortController();
  let timedOut = false;
  const cancel = () => controller.abort();
  signal.addEventListener("abort", cancel, { once: true });
  if (signal.aborted) cancel();
  const timeout = setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, searchConfiguration.timeoutMs);

  try {
    const params = new URLSearchParams({
      term,
      max_entries: String(searchConfiguration.maxEntriesPerType),
      strictness: String(strictness),
    });
    const response = await fetch(`${origin}/search?${params}`, {
      signal: controller.signal,
    });
    if (!response.ok) {
      throw new Error(
        "The search service is unavailable. Try again in a moment.",
      );
    }
    const body: unknown = await response.json();
    return readEntities(body);
  } catch (error) {
    if (timedOut) throw new Error("Search is taking too long. Try again.");
    if (signal.aborted) throw error;
    if (error instanceof TypeError || error instanceof SyntaxError) {
      throw new Error(
        "Couldn’t connect to search. Check your connection and try again.",
      );
    }
    throw error;
  } finally {
    clearTimeout(timeout);
    signal.removeEventListener("abort", cancel);
  }
}

export type DetailRoute =
  | { kind: "search" }
  | { kind: "member"; id: string; view: "summary" | "history" }
  | { kind: "funder"; id: string; view: "summary" | "history" }
  | { kind: "invalid" };

export const funderIdPattern =
  /^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/iu;
export const memberIdPattern = /^[1-9]\d*$/u;

export function readDetailRoute(path: string): DetailRoute {
  if (path === "/") return { kind: "search" };
  const member = /^\/members\/([^/]+)(?:\/(history))?\/?$/u.exec(path);
  if (
    member &&
    memberIdPattern.test(member[1]) &&
    Number(member[1]) <= 2147483647
  )
    return {
      kind: "member",
      id: member[1],
      view: member[2] ? "history" : "summary",
    };
  const funder = /^\/funders\/([^/]+)(?:\/(history))?\/?$/u.exec(path);
  if (funder && funderIdPattern.test(funder[1]))
    return {
      kind: "funder",
      id: funder[1],
      view: funder[2] ? "history" : "summary",
    };
  return { kind: "invalid" };
}

export interface MemberProfile {
  id: string;
  name: string;
  partyName: string;
  membershipFrom: string;
  isCurrentCommons: boolean;
}

export interface FundingEntry {
  funder: { id: string; name: string } | null;
  amount: string | null;
  currency: string | null;
  paymentType: string | null;
}

export interface MemberDeclaration {
  sourceId: number;
  categoryId: number;
  categoryName: string;
  registeredAt: string | null;
  entries: FundingEntry[];
}

export interface MemberDetails {
  member: MemberProfile;
  declarations: MemberDeclaration[];
  summary: {
    currencies: (Total & {
      currency: string;
      categories: (Total & { categoryId: number; categoryName: string })[];
    })[];
    entryCount: number;
    unknownCurrencyCount: number;
    firstRegisteredAt: string | null;
    lastRegisteredAt: string | null;
    undatedDeclarationCount: number;
  };
}

export interface Total {
  amount: string | null;
  entryCount: number;
  unknownAmountCount: number;
}

export interface FunderDeclaration {
  member: MemberProfile;
  declaration: MemberDeclaration;
}

export interface FunderDetails {
  declarations: FunderDeclaration[];
  funder: {
    id: string;
    name: string;
    funderKind: string | null;
    companyNumber: string | null;
    aliases: string[];
  };
  currencies: {
    currency: string;
    amount: string | null;
    parties: (Total & { partyName: string })[];
    topRecipients: (Total & { member: MemberProfile })[];
  }[];
  entryCount: number;
  unknownCurrencyCount: number;
  recipientLimit: number;
}

export type DetailState =
  | { kind: "loading" }
  | { kind: "member"; details: MemberDetails }
  | { kind: "funder"; details: FunderDetails }
  | { kind: "not-found" }
  | { kind: "error"; message: string };

export function backToSearch(params: Pick<URLSearchParams, "get">): string {
  const retained = new URLSearchParams();
  for (const key of ["q", "strictness"]) {
    const value = params.get(key);
    if (value !== null) retained.set(key, value);
  }
  return retained.size ? `/?${retained}` : "/";
}

export function formatAmount(value: string | null): string {
  if (value === null) return "Amount unavailable";
  const negative = value.startsWith("-");
  const unsigned = negative ? value.slice(1) : value;
  const [whole, fraction] = unsigned.split(".");
  return `${negative ? "−" : ""}${whole.replace(/\B(?=(\d{3})+(?!\d))/gu, ",")}${fraction === undefined ? "" : `.${fraction}`}`;
}

export function registrationDate(value: string): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(value));
}

export function memberHref(
  id: string,
  view: "summary" | "history",
  params: Pick<URLSearchParams, "get">,
): string {
  const search = backToSearch(params).slice(1);
  return `/members/${id}${view === "history" ? "/history" : ""}${search}`;
}

export function categoryBars(
  categories: { amount: string | null }[],
  basis: "total" | "maximum",
): { width: number; negative: boolean }[] {
  const scale = Math.max(
    0,
    ...categories.map(({ amount }) => amount?.split(".")[1]?.length ?? 0),
  );
  const values = categories.map(({ amount }) => {
    if (amount === null) return 0n;
    const [whole, fraction = ""] = amount.replace(/^-/, "").split(".");
    const value = BigInt(whole + fraction.padEnd(scale, "0"));
    return amount.startsWith("-") ? -value : value;
  });
  const magnitudes = values.map((value) => (value < 0n ? -value : value));
  let denominator: bigint;
  let precision: bigint;
  switch (basis) {
    case "total":
      denominator = magnitudes.reduce((total, value) => total + value, 0n);
      precision = 100000000n;
      break;
    case "maximum":
      denominator = magnitudes.reduce(
        (largest, value) => (value > largest ? value : largest),
        0n,
      );
      precision = 100n;
      break;
    default: {
      const exhaustive: never = basis;
      return exhaustive;
    }
  }
  return values.map((value, index) => ({
    negative: value < 0n,
    width:
      denominator === 0n
        ? 0
        : Number((magnitudes[index] * 100n * precision) / denominator) /
          Number(precision),
  }));
}

export function funderHref(
  id: string,
  view: "summary" | "history",
  params: Pick<URLSearchParams, "get">,
): string {
  const search = backToSearch(params).slice(1);
  return `/funders/${id}${view === "history" ? "/history" : ""}${search}`;
}

// Search defaults live here. The API applies
// max_entries independently to MPs and funders, then merges by similarity.
export const searchConfiguration = {
  minimumCharacters: 3,
  debounceMs: 250,
  maxEntriesPerType: 10,
  strictness: 0.8,
  timeoutMs: 10_000,
};

export function readStrictness(value: string | null): number {
  if (!value?.trim()) return searchConfiguration.strictness;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 && parsed <= 1
    ? Math.round(parsed * 100) / 100
    : searchConfiguration.strictness;
}

export type SearchMatchSource =
  { kind: "name" } | { kind: "alias"; name: string };

export type Entity =
  | {
      id: string;
      name: string;
      kind: "MP";
      funderKind: null;
      matchSource: { kind: "name" };
    }
  | {
      id: string;
      name: string;
      kind: "Funder";
      funderKind: string | null;
      matchSource: SearchMatchSource;
    };

export function entityHref(
  entity: Pick<Entity, "kind" | "id">,
  params: Pick<URLSearchParams, "get">,
): string {
  const retained = new URLSearchParams();
  for (const key of ["q", "strictness"]) {
    const value = params.get(key);
    if (value !== null) retained.set(key, value);
  }
  const query = retained.size ? `?${retained}` : "";
  return `/${entity.kind === "MP" ? "members" : "funders"}/${encodeURIComponent(entity.id)}${query}`;
}

export function entityType(entity: Entity): string {
  if (entity.kind === "MP") return "MP";
  return `Funder: ${funderKindLabel(entity.funderKind)}`;
}

export function funderKindLabel(value: string | null): string {
  const kind = value?.trim();
  if (!kind || kind.toLowerCase() === "not specified") return "Unclassified";
  if (kind.toLowerCase() === "individual") return "Individual";
  if (kind.toLowerCase() === "company") return "Company";
  if (kind.toLowerCase() === "trade union") return "Trade union";
  return kind;
}

export function funderKindIcon(value: string | null) {
  switch (funderKindLabel(value).toLowerCase()) {
    case "individual":
      return "person";
    case "company":
      return "building";
    case "trade union":
      return "group";
    case "unclassified":
      return "question";
    default:
      return "tag";
  }
}

// Plain-text segments keep source names intact and never interpret names or
// user input as markup. Matching here only highlights; it never changes rank.
export function highlightName(name: string, term: string) {
  const tokens = [...new Set(term.trim().split(/\s+/u).filter(Boolean))]
    .sort((a, b) => b.length - a.length)
    .map((token) => token.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  if (!tokens.length) return [{ text: name, matched: false }];
  const pattern = new RegExp(tokens.join("|"), "giu");
  const segments: { text: string; matched: boolean }[] = [];
  let position = 0;
  for (const match of name.matchAll(pattern)) {
    const start = match.index;
    if (start > position)
      segments.push({ text: name.slice(position, start), matched: false });
    segments.push({ text: match[0], matched: true });
    position = start + match[0].length;
  }
  if (position < name.length)
    segments.push({ text: name.slice(position), matched: false });
  return segments;
}

import { defineConfig, devices } from "@playwright/test";

export default defineConfig({
  testDir: "./tests",
  fullyParallel: true,
  forbidOnly: Boolean(process.env.CI),
  retries: 0,
  reporter: "list",
  use: {
    baseURL: "http://127.0.0.1:4173",
    ...devices["Desktop Chrome"],
    trace: "retain-on-failure",
  },
});

